class Solution {
public:
    ListNode* deleteDuplicatesUnsorted(ListNode* head) {
        unordered_map<int, int> counts;
        ListNode* curr = head;
        while (curr) {
            counts[curr->val]++;
            curr = curr->next;
        }

        ListNode dummy(0);
        ListNode* tail = &dummy;
        curr = head;
        while (curr) {
            if (counts[curr->val] == 1) {
                tail->next = curr;
                tail = tail->next;
            }
            curr = curr->next;
        }
        tail->next = nullptr;
        return dummy.next;
    }
};

class Solution {
    public ListNode deleteDuplicatesUnsorted(ListNode head) {
        Map<Integer, Integer> counts = new HashMap<>();
        ListNode curr = head;
        while (curr != null) {
            counts.put(curr.val, counts.getOrDefault(curr.val, 0) + 1);
            curr = curr.next;
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        curr = head;
        while (curr != null) {
            if (counts.get(curr.val) == 1) {
                tail.next = curr;
                tail = tail.next;
            }
            curr = curr.next;
        }
        tail.next = null;
        return dummy.next;
    }
}

var deleteDuplicatesUnsorted = function(head) {
  const counts = new Map();
  let curr = head;
  while (curr) {
    counts.set(curr.val, (counts.get(curr.val) || 0) + 1);
    curr = curr.next;
  }

  const dummy = new ListNode(0);
  let tail = dummy;
  curr = head;
  while (curr) {
    if (counts.get(curr.val) === 1) {
      tail.next = curr;
      tail = tail.next;
    }
    curr = curr.next;
  }
  tail.next = null;
  return dummy.next;
